# Code generated by Claude
"""
The new neck framing rule (design plan 14.1, decisions-log M135 and M151) against the old one, at the staging's handoff pose (the staging stance, arms at home, the neck at the drive pose).

    MUJOCO_GL=egl python experiments/neck_rule_test.py [--out docs/reports]

1. Old rule (aim at the centre of the points' bounding box) and new rule (least movement from the driving pose, 10 % margin): the neck joint targets, the movement from the driving pose, the worst margin,
   the aim error, the camera's position and direction, the time per framing, and the eagle camera's image with each (two PNG files, side by side in one).
2. Repeatability: the old rule's 8 jiggled solves and the new rule's 2 (the arms' joints get 0.1 degree of noise, as neck_spread), the largest change of any neck joint.
3. The null step: the pose is kept while every point is more than 5 % inside the image; below that the neck moves the least needed from where it is to restore 10 %.
4. The default is the old rule (nothing else changes).
"""

import argparse
import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from neck_framing_test import place_handoff  # noqa: E402
from src import robot_specs  # noqa: E402
from src.neck import neck_ids, set_neck_pose  # noqa: E402
from src.neck_framing import FRAMING_CFG, frame_points, margins_at, reframe_or_keep, _Scratch  # noqa: E402
from src.task_beaker_hotplate import framing_points, load_task, spawn_and_settle  # noqa: E402
from src.task_config import FULLCHECK_CFG  # noqa: E402

results = []
NS = robot_specs.NECK_SPECS


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def timed(model, data, pts, rule, n=3):
    ts, out = [], None
    for _ in range(n):
        t0 = time.perf_counter()
        out = frame_points(model, data, pts, {"rule": rule})
        ts.append(time.perf_counter() - t0)
    return out, float(np.mean(ts))


def render(model, data, q, path):
    set_neck_pose(model, data, NS, [q[n] for n in NS["active_joints"]])
    mujoco.mj_forward(model, data)
    W, H = [int(v) for v in model.cam_resolution[model.camera("eagle_cam").id]]
    r = mujoco.Renderer(model, H, W)
    r.update_scene(data, camera="eagle_cam")
    img = r.render().copy()
    r.close()
    cv2.imwrite(str(path), cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
    return img


def spread(model, data, pts_fn, rule, n, noise=1.7e-3, seed=1):
    t1, _ = frame_points(model, data, pts_fn(model, data), {"rule": rule})
    rng, q0, worst = np.random.default_rng(seed), data.qpos.copy(), 0.0
    for _ in range(n):
        data.qpos[:] = q0
        for sd in ("left", "right"):
            for i in range(1, 8):
                data.qpos[model.joint(f"openarm_{sd}_joint{i}").qposadr[0]] += noise * rng.standard_normal()
        mujoco.mj_kinematics(model, data)
        tp, _ = frame_points(model, data, pts_fn(model, data), {"rule": rule})
        worst = max(worst, max(abs(tp[j] - t1[j]) for j in t1))
    data.qpos[:] = q0
    mujoco.mj_kinematics(model, data)
    return float(worst)


def main(out):
    out = Path(out)
    out.mkdir(parents=True, exist_ok=True)
    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    spawn_and_settle(sim)
    place_handoff(sim)
    mujoco.mj_forward(model, data)
    pts = framing_points(model, data)
    q_drive = np.array(NS["drive_pose"], float)
    names = NS["active_joints"]

    print("1. old rule and new rule at the handoff pose")
    (t_old, r_old), s_old = timed(model, data, pts, "aim_centre")
    (t_new, r_new), s_new = timed(model, data, pts, "least_movement")
    mv = lambda t: float(np.linalg.norm([t[n] - q for n, q in zip(names, q_drive)]))
    for tag, t, r, s in (("old (aim at the box centre)", t_old, r_old, s_old), ("new (least movement)", t_new, r_new, s_new)):
        print(f"  {tag}: movement from the drive pose {mv(t):.3f} rad; worst margin {100 * r['worst_margin']:.2f} %, aim error {r['aim_error_deg']:.2f} deg, camera at {r['camera_pos']}, {s:.2f} s per framing; targets {[round(t[n], 3) for n in names]}")
    img_old = render(model, data, t_old, out / "neck_rule_old.png")
    img_new = render(model, data, t_new, out / "neck_rule_new.png")
    cv2.imwrite(str(out / "neck_rule_old_vs_new.png"), cv2.cvtColor(np.hstack([img_old, img_new]), cv2.COLOR_RGB2BGR))
    print(f"  images: {out / 'neck_rule_old_vs_new.png'} (left old, right new)")
    check("the old rule frames with the 10 % margin", r_old["fits"], f"{100 * r_old['worst_margin']:.2f} %")
    check("the new rule frames with the 10 % margin", r_new["fits"] and r_new["worst_margin"] >= 0.10 - 1e-6, f"{100 * r_new['worst_margin']:.2f} %")
    check("the new rule moves the neck no more than the old one (least movement from the driving pose)", mv(t_new) <= mv(t_old) + 1e-6, f"new {mv(t_new):.3f} rad, old {mv(t_old):.3f} rad")
    check("no neck contacts under the new rule", not r_new["contacts"], f"{r_new['contacts']}")

    print("\n2. repeatability")
    set_neck_pose(model, data, NS)
    mujoco.mj_forward(model, data)
    sp_old = spread(model, data, framing_points, "aim_centre", 8)
    sp_new = spread(model, data, framing_points, "least_movement", 2)
    sp_new8 = spread(model, data, framing_points, "least_movement", 8)
    print(f"  old rule, 8 draws: largest joint change {sp_old:.4f} rad; new rule, 2 draws: {sp_new:.4f} rad (8 draws for comparison: {sp_new8:.4f} rad)")
    check("the new rule's 2 jiggled solves agree within 0.06 rad (the repeatability limit of neck_once_test)", sp_new <= 0.06, f"{sp_new:.4f} rad")

    print("\n3. the null step")
    set_neck_pose(model, data, NS, [t_new[n] for n in names])
    mujoco.mj_forward(model, data)
    q_cur = np.array([data.qpos[a] for a in neck_ids(model, NS)["qadr"]])
    tk, rk, moved = reframe_or_keep(model, data, pts)
    check("the targets sit at the 10 % margin (more than 5 % inside): the pose is kept, nothing moves", not moved and all(abs(tk[n] - q) < 1e-12 for n, q in zip(names, q_cur)), f"worst margin {100 * rk['worst_margin']:.2f} %")
    keep_case = move_case = None
    for s in np.arange(0.0, 0.40, 0.01):
        shifted = {k: (np.asarray(v) + np.array([s, 0, 0])).tolist() for k, v in pts.items()}
        mn = min(margins_at(model, data, shifted).values())
        if mn <= 0.099 and keep_case is None and mn > 0.05:
            keep_case = (s, mn, shifted)
        if mn <= 0.05 and move_case is None:
            move_case = (s, mn, shifted)
            break
    print(f"  shifting the targets sideways: first below the 10 % line at {None if keep_case is None else round(keep_case[0], 2)} m (margin {None if keep_case is None else round(100 * keep_case[1], 1)} %), at or below 5 % at {None if move_case is None else round(move_case[0], 2)} m (margin {None if move_case is None else round(100 * move_case[1], 1)} %)")
    if keep_case:
        tk, rk, moved = reframe_or_keep(model, data, keep_case[2])
        check("a point between 5 % and 10 % inside: the pose is kept (the margin may sit below 10 %)", not moved, f"margin {100 * keep_case[1]:.1f} %")
    if move_case:
        tm, rm, moved = reframe_or_keep(model, data, move_case[2])
        d_cur = float(np.linalg.norm([tm[n] - q for n, q in zip(names, q_cur)]))
        (t_fresh, _), _ = timed(model, data, move_case[2], "aim_centre", n=1)
        d_fresh = float(np.linalg.norm([t_fresh[n] - q for n, q in zip(names, q_cur)]))
        print(f"  at or below 5 %: moved {moved}, new worst margin {100 * rm['worst_margin']:.2f} %, movement from the current pose {d_cur:.3f} rad (the old rule from scratch would move {d_fresh:.3f} rad)")
        check("at or below 5 %: the neck moves, restores the 10 % margin, and moves less than the old rule would", moved and rm["fits"] and d_cur <= d_fresh + 1e-6, f"{d_cur:.3f} vs {d_fresh:.3f} rad")
    check("the keep and move cases were both found in the scan", keep_case is not None and move_case is not None)

    print("\n4. the defaults")
    check("FRAMING_CFG['rule'] is 'aim_centre' (the old rule) and the repeatability draws under the new rule are 2", FRAMING_CFG["rule"] == "aim_centre" and FULLCHECK_CFG["neck_draws_least_movement"] == 2)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(PROJECT_ROOT / "docs" / "reports"))
    sys.exit(0 if main(ap.parse_args().out) else 1)
